probe(bsr_bad_right_improper_list) -> erlang370_pure_support:invoke('bsr',[1,[1|tail]]);
probe(bsr_bad_left_tuple) -> erlang370_pure_support:invoke('bsr',[{x,1},1]);
probe(bsr_bad_right_tuple) -> erlang370_pure_support:invoke('bsr',[1,{x,1}]);
probe(bsr_bad_left_map) -> erlang370_pure_support:invoke('bsr',[#{1=>a},1]);
probe(bsr_bad_right_map) -> erlang370_pure_support:invoke('bsr',[1,#{1=>a}]);
probe(bsr_bad_left_binary) -> erlang370_pure_support:invoke('bsr',[<<0>>,1]);
probe(bsr_bad_right_binary) -> erlang370_pure_support:invoke('bsr',[1,<<0>>]);
probe(bsr_bad_left_bits) -> erlang370_pure_support:invoke('bsr',[<<1:1>>,1]);
probe(bsr_bad_right_bits) -> erlang370_pure_support:invoke('bsr',[1,<<1:1>>]);
probe(bsr_bad_left_float) -> erlang370_pure_support:invoke('bsr',[1.0,1]);
probe(bsr_bad_right_float) -> erlang370_pure_support:invoke('bsr',[1,1.0]).
